mapper.select:
select a.* from (select a.book_id, a.book_name, a.author, a.publisher, a.publish_date, a.kind, a.book_num, a.create_time,
(select count(*) from book_borrow_record b where b.book_id=a.book_id

    and DATE_ADD(b.borrow_time,INTERVAL #{params.nearlyDay} DAY) >= now()

) borrowNum,
(SELECT CONVERT(avg((UNIX_TIMESTAMP(b.return_time)-UNIX_TIMESTAMP(b.borrow_time))*1000), UNSIGNED INTEGER)
from book_borrow_record b WHERE b.`status`=1 and b.book_id=a.book_id) millSeconds
from book_info a)a

     and a.book_id = #{bookId}
      and a.book_name like concat('%',#{bookName},'%') 
      and a.author like concat('%',#{author},'%')
      and a.publisher = #{publisher}
      and a.publish_date = #{publishDate}
      and a.kind = #{kind}
      and a.book_num = #{bookNum}
      and a.create_time = #{createTime}

        and a.borrowNum >= #{params.minNum}


        and a.borrowNum <= #{params.maxNum}


        and a.millSeconds >= #{params.minMillSec}


        and a.millSeconds <= #{params.maxMillSec}


        and a.book_id in(
        select DISTINCT book_id from book_borrow_record where DATE_ADD(borrow_time,INTERVAL #{params.nearlyDay} DAY) >= now()
        )

mapper.update:
update book_info
book_name = #{bookName}, author = #{author}, publisher = #{publisher}, publish_date = #{publishDate}, kind = #{kind}, book_num = #{bookNum}, create_time = #{createTime},
where book_id = #{bookId}
